Fixes: 4a5fe57e7751 ("alx: use fine-grained locking instead of RTNL")
Reported-and-tested-by: Zbynek Michl <zbynek.michl@gmail.com>
Reviewed-by: Niels Dossche <dossche.niels@gmail.com>
Link: https://lore.kernel.org/r/20220928181236.1053043-1-kuba@kernel.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by the absence of `rtnl_lock` during the internal close and re-open operations of the alx driver during the suspend and resume processes. This lack of proper locking can lead to race conditions and trigger an assertion failure in the networking subsystem, specifically when the driver attempts to set the number of transmit queues without holding the necessary lock.

Here is the patch:
 #ifdef CONFIG_PM_SLEEP
 static int alx_suspend(struct device *dev)
 {
 	struct alx_priv *alx = dev_get_drvdata(dev);

 	if (!netif_running(alx->dev))
 		return 0;
+
+	rtnl_lock();
 	netif_device_detach(alx->dev);

 	mutex_lock(&alx->mtx);
 	__alx_stop(alx);
 	mutex_unlock(&alx->mtx);
+	rtnl_unlock();

 	return 0;
 }

 static int alx_resume(struct device *dev)
 {
 	struct alx_priv *alx = dev_get_drvdata(dev);
 	struct alx_hw *hw = &alx->hw;
 	int err;

+	rtnl_lock();
 	mutex_lock(&alx->mtx);
 	alx_reset_phy(hw);

 	if (!netif_running(alx->dev)) {
 		err = 0;
 		goto unlock;
 	}

 	err = __alx_open(alx, true);
 	if (err)
 		goto unlock;

 	netif_device_attach(alx->dev);

 unlock:
 	mutex_unlock(&alx->mtx);
+	rtnl_unlock();
 	return err;
 }



